export class DadAdminPanel{constructor(g){this.g=g;document.querySelector('#parents').onclick=()=>{g.panel('<h2>Área dos responsáveis</h2><p>Quanto é 7 + 5?</p><input id="answer" inputmode="numeric" aria-label="Resposta"><button id="unlock">Abrir</button>');document.querySelector('#unlock').onclick=()=>{if(document.querySelector('#answer').value!=='12')return;g.panel('<h2>🎁 Presentes do Papai</h2><button id="gift">🪙 +1000</button><button id="eggGift">🥚 Ovo especial</button><button id="giant">🦖 Gigante</button><button id="teleport">🏠 Voltar</button>');document.querySelector('#gift').onclick=()=>g.reward(1000);document.querySelector('#eggGift').onclick=()=>{g.save.data.eggs++;g.save.save();g.notify('🥚 Presente recebido')};document.querySelector('#giant').onclick=()=>g.player.scale.setScalar(g.player.scale.x===1?1.7:1);document.querySelector('#teleport').onclick=()=>g.player.position.set(0,0,10)}}}}
